function audit = validate_m18_traceability(e, numericAudit)
%VALIDATE_M18_TRACEABILITY Cross-check final claims against source artifacts.
arguments
    e (1,1) struct = load_m18_validated_artifacts
    numericAudit table = build_m18_report_values(e)
end
s=e.m16.stabilitySummary; sample5=e.m16.stabilityTable(e.m16.stabilityTable.Controller=="M6" & e.m16.stabilityTable.Sample==5,:); roles=e.m17.finalRoleAssignment;
label=["Controller identity audit M17";"Controller orders 14/18/52";"M16 sample count";"M16 stability counts";"M6 Sample 5 instability";"Kmu RS margin M14";"Kmu NP/RP M14";"Final role selection M17";"RAS empirical semantics";"uScale normalization semantics";"Monte Carlo empirical semantics";"M7 status preserved";"M9 status preserved";"M10 status preserved";"M11 status preserved";"M12 status preserved";"M14 status preserved";"M15 status preserved";"All numeric rows source-mapped"];
passed=[all(e.m17.controllerIdentityAudit.IdentityPassed);isequal([order(e.m6.Klqg);order(e.m10.Khinf);order(e.m13.Kmu)],[14;18;52]);e.m16.numberSamples==40;isequal(s.NStable,[39;40;40]);height(sample5)==1&&~sample5.Stable&&sample5.MaxRealPole>0;e.m14.robustStabilityMargin.LowerBound>1&&e.m14.robustStabilityMargin.UpperBound>e.m14.robustStabilityMargin.LowerBound;string(e.m14.qualityGate.nominalPerformance)=="FAIL"&&string(e.m14.qualityGate.robustPerformance)=="FAIL_CERTIFIED";roles.Controller(roles.Role=="FINAL ROBUST CONTROLLER")=="Kmu"&&roles.Controller(roles.Role=="NOMINAL PERFORMANCE REFERENCE")=="M6"&&roles.Controller(roles.Role=="H-INFINITY REFERENCE / COMPARATOR")=="Khinf";~any(e.m17.rasComparison.AnalyticallyCertified)&&all(contains(e.m17.rasComparison.Interpretation,"EMPIRICAL"));contains(string(e.m5.spec.controlEffortScaleMeaning),"normalization")&&contains(e.config.uScaleInterpretation,"NOT_CERTIFIED_SATURATION");contains(e.config.monteCarloInterpretation,"NOT_A_ROBUSTNESS_CERTIFICATE");string(e.m7.validationMetrics.status)=="PARTIAL";string(e.m9.qualityGate.overallStatus)=="PARTIAL";string(e.m10.qualityGate.overallStatus)=="PARTIAL";string(e.m11.qualityGate.overallStatus)=="PARTIAL";string(e.m12.qualityGate.overallStatus)=="PARTIAL";string(e.m14.qualityGate.overallStatus)=="PARTIAL";string(e.m15.qualityGate.overallStatus)=="PARTIAL";all(strlength(numericAudit.SourceMilestone)>0&strlength(numericAudit.SourceArtifact)>0&strlength(numericAudit.SourceField)>0&strlength(numericAudit.ReportMacro_Table)>0)];
details=repmat("read directly from frozen artifact",numel(label),1); details(end)="every generated numeric row has a source mapping";
audit=table(label,passed,details,'VariableNames',{'Check','Passed','Details'});
assert(all(audit.Passed),"M18:TraceabilityFailure","M18 mismatch: %s",strjoin(audit.Check(~audit.Passed),", "));
end
